return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Dutch','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:04+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'nl_NL','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Meertalige routing, SEO-meta-tags en AI-inhoudtools voor WordPress. Combineert taalherkenning, URL-routing, hreflang, metabeschrijvingen en AI-gestuurde fragmenten, meta\'s en vertaalfuncties.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Vertalen','Lingua Forge — Quick Translate'=>'Lingua Forge — Snelle Vertaling','Informative'=>'Informatief','Persuasive'=>'Overtuigend','Storytelling'=>'Storytelling','Technical'=>'Technisch','Conversational'=>'Conversatie','Permission denied.'=>'Toestemming geweigerd.','Cannot determine target language from slug.'=>'Kan doeltaal niet bepalen uit slug.','Invalid post type.'=>'Ongeldig berichttype.','Invalid or primary language.'=>'Ongeldige of primaire taal.','Template not found or not stored in the database.'=>'Sjabloon niet gevonden of niet opgeslagen in de database.','Template has no content.'=>'Sjabloon heeft geen inhoud.','No internal links found to update.'=>'Geen interne links gevonden om bij te werken.','%d link updated.'=>'%d link bijgewerkt.' . "\0" . '%d links bijgewerkt.','No language-specific template parts found to map.'=>'Geen taal-specifieke sjabloononderdelen gevonden om te koppelen.','No template part references needed updating.'=>'Geen sjabloononderdeelreferenties die bijgewerkt hoeven te worden.','%d part reference updated.'=>'%d onderdeelreferentie bijgewerkt.' . "\0" . '%d onderdeelreferenties bijgewerkt.','Invalid language.'=>'Ongeldige taal.','Template part not found or not stored in the database.'=>'Sjabloononderdeel niet gevonden of niet opgeslagen in de database.','Template part has no content.'=>'Sjabloononderdeel heeft geen inhoud.','No navigation references needed updating.'=>'Geen navigatielinks die bijgewerkt hoeven te worden.','%d navigation reference updated.'=>'%d navigatielink bijgewerkt.' . "\0" . '%d navigatielinks bijgewerkt.','No AI provider configured.'=>'Geen AI-provider geconfigureerd.','Missing pattern name or language.'=>'Ontbrekende patroonnaam of taal.','Pattern not found.'=>'Patroon niet gevonden.','Pattern has no content to translate.'=>'Patroon heeft geen inhoud om te vertalen.','AI provider returned an empty response.'=>'AI-provider gaf een lege reactie.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroon vertaald en opgeslagen. Kopieer de inhoud naar je CPT-bericht via de blokeditor Pattern-inserter of gebruik het als startpunt voor een Herbruikbaar Blok.','Invalid template type.'=>'Ongeldig sjabloontype.','Template "%s" already exists.'=>'"%s" bestaat al.','"%s" created.'=>'"%s" gemaakt.','Invalid template part.'=>'Ongeldig sjabloononderdeel.','Template part "%s" already exists.'=>'"%s" bestaat al.','"%1$s" created. %2$d template updated.'=>'"%1$s" gemaakt. %2$d sjabloon bijgewerkt.' . "\0" . '"%1$s" gemaakt. %2$d sjablonen bijgewerkt.','Page'=>'Pagina','Single'=>'Enkelvoudig','Search'=>'Zoeken','Search Results'=>'Zoekresultaten','Archive'=>'Archief','Front Page'=>'Voorpagina','Single: %s'=>'Enkelvoud: %s','Single %s'=>'Enkelvoud %s','Archive: %s'=>'Archief: %s','%s Archive'=>'%s Archief','No source content found to translate.'=>'Geen broninhoud gevonden om te vertalen.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Vertaald. Bekijk in de Site Editor — interne links, navigatie-URL\'s en sjabloon-slugs worden niet automatisch bijgewerkt.','Navigation not found.'=>'Navigatie niet gevonden.','Navigation has no content to translate.'=>'Navigatie bevat geen inhoud om te vertalen.','"%1$s %2$s" saved.'=>'"%1$s %2$s" opgeslagen.','Translate page…'=>'Pagina vertalen…','Generate content…'=>'Inhoud genereren…','AI Behaviour Preset'=>'AI Gedragsvoorinstelling','Custom'=>'Aangepast','Global default (%s)'=>'Standaard wereldwijd (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Overschrijft de AI-voorinstelling voor Vertaling en Inhoudsgeneratie op deze pagina. Site-brede aangepaste instructies (Instellingen → Gedrag) worden altijd toegevoegd aan elk verzoek, ongeacht deze selectie.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Overschrijft de AI-voorinstelling voor Vertaling en Inhoudsgeneratie op deze pagina. Alle andere functies gebruiken altijd de wereldwijde voorinstelling.','Close'=>'Sluiten','Translate missing'=>'Vertaling ontbreekt','From'=>'Van','Retranslate'=>'Vertaal opnieuw','Translating…'=>'Bezig met vertalen…','Retranslating…'=>'Hervertalen…','✓ Done'=>'✓ Gereed','Error'=>'Fout','Navigation posts are translated via the Router tab, not this button.'=>'Navigatieberichten worden vertaald via het Router-tabblad, niet via deze knop.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Het maken van vertalingen voor berichttype "%s" vereist een actieve integratie. Zorg ervoor dat de benodigde integratie is geïnstalleerd en actief.','No %s version found in this translation group.'=>'Geen %s-versie gevonden in deze vertalingsgroep.','AI Usage'=>'AI-gebruik','Today'=>'Vandaag','Last 7 days'=>'Afgelopen 7 dagen','Last 30 days'=>'Afgelopen 30 dagen','All time'=>'Alles','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Tokenverbruik opgeteld per functie, provider en model. Geregistreerd bij elke succesvolle AI-aanroep; Testverbinding-pings worden opzettelijk uitgesloten zodat ze de totalen niet vertekenen. De onderliggende tabel aggregeert dagelijks — kies een venster hieronder om het te bekijken.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Nog geen AI-gebruik geregistreerd. Zodra een editor een vertaling uitvoert, een meta-beschrijving genereert of een andere AI-functie gebruikt, verschijnen de totalen hier.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Geen AI-gebruik geregistreerd in het geselecteerde venster (%s). Kies een breder bereik hierboven.','Feature'=>'Functie','Provider'=>'Provider','Model'=>'Model','Requests'=>'Verzoeken','Input tokens'=>'Invoertokens','Output tokens'=>'Uitvoertokens','Total tokens'=>'Totaal tokens','Total'=>'Totaal','API Keys'=>'API-sleutels','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Sleutels worden versleuteld met AES-256-CBC voordat ze in de WordPress-database worden opgeslagen. Het encryptiegeheim wordt afgeleid van je WordPress-authentificatiesalts (wp-config.php), zodat platte tekst-sleutels nooit de database raken.','API Key'=>'API-sleutel','Paste your API key…'=>'Plak je API-sleutel…','✓ Configured'=>'✓ Geconfigureerd','✗ Not configured'=>'✗ Niet geconfigureerd','Test connection'=>'Testverbinding','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Laat leeg om de bestaande sleutel te behouden. Voer een nieuwe waarde in om deze te vervangen.','Remove stored key'=>'Verwijder opgeslagen sleutel','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Deze sleutel wordt momenteel geleverd door een server %s en kan hier niet worden verwijderd. Voer een nieuwe sleutel hierboven in om deze te overschrijven met een databasewaarde.','environment variable'=>'omgevingsvariabele','PHP constant'=>'PHP-constante','Alternative (server-side):'=>'Alternatief (serverzijde):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Je kunt sleutels ook definiëren als constanten of omgevingsvariabelen (bijvoorbeeld in wp-config.php). Die bronnen worden automatisch gebruikt als fallback wanneer er geen database-sleutel is opgeslagen.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Om een aangepaste encryptiegeheim te gebruiken (in plaats van de afgeleide wp_salt-waarde), voeg dit toe aan wp-config.php:','Unknown provider.'=>'Onbekende provider.','No API key configured for this provider.'=>'Geen API-sleutel geconfigureerd voor deze provider.','Could not instantiate the provider.'=>'Kon de provider niet initialiseren.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Provider gaf geen tekst terug. Controleer het WordPress-foutlog voor de gedetailleerde reden van de fout.','Behavior'=>'Gedrag','Block Editor'=>'Block Editor','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge beperkt standaard twee Gutenberg-functies om het redactionele gedrag consistent te houden over talen. Meld je hier aan als je volledige Gutenberg / FSE-mogelijkheden nodig hebt.','Block locking'=>'Blokvergrendeling','Allow editors to lock individual blocks'=>'Sta redacteuren toe om individuele blokken te vergrendelen','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Heractiveert Gutenberg\'s canLockBlocks. Handig voor redactionele sjablonen die voorkomen dat bijdragers bepaalde blokken verplaatsen of verwijderen.','Template mode'=>'Sjabloonmodus','Allow Gutenberg template-editing mode on post screens'=>'Sta Gutenberg sjabloonbewerkingsmodus toe op berichtenschermen','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Heractiveert supportsTemplateMode. Kern voor workflows met volledige site-bewerking waar op berichtniveau sjabloonoverschrijvingen opzettelijk zijn.','Compliance Preset'=>'Nalevingspreset','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strikte-preservatiemodus voor juridische, regelgevende, medische of technische inhoud. Wanneer ingeschakeld, gebruikt elke AI-functie een lage bemonsteringstemperatuur en voegt de onderstaand addendum toe aan de systeemprompt — terminologie, artikelnummers, eenheden, merknamen en regelgeving worden letterlijk behouden in plaats van te worden geparafraseerd.','Global AI preset'=>'Globale AI-preset','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per functie','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Stelt het standaard AI-gedrag in voor alle functies site-breed. Individuele berichten kunnen dit overschrijven voor Vertaling en Inhoudsgeneratie via de Lingua Forge meta box.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standaard gebruikt de eigen afgestelde temperatuur van elke functie: Vertaling T=0.2 (nauwkeurig), Snelle Vertaling T=0.4, Inhoudsgenerator T=0.6 (creatief). De andere presets passen een enkele vaste temperatuur toe op alle functies.','Technical / Scientific instructions'=>'Technische / Wetenschappelijke instructies','Legal / Compliance instructions'=>'Juridische / Nalevingsinstructies','Creative / Marketing instructions'=>'Creatieve / Marketing instructies','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Laat leeg om de ingebouwde standaard te gebruiken. Het wissen van een opgeslagen overschrijving herstelt de standaard bij de volgende opslag.','View built-in default'=>'Bekijk ingebouwde standaard','Translation Memory'=>'Vertalingsgeheugen','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache vertaalde equivalenten op blokniveau zodat herbruikbare inhoud (gedeelde voetteksten, zijbalken, accordions, juridische secties met veel boilerplate) niet elke keer een API-aanroep doen. Wanneer ingeschakeld, parseert de vertaalstroom elk bericht in blokken, zoekt elk blok op in de cache, en stuurt alleen niet-geladen blokken naar de AI in één batch-aanvraag. Wijzigingen in woordenlijst en nalevingspreset maken automatisch de getroffen cache-vertalingen ongeldig. Bekijk statistieken en wis de cache onder Onderhoud.','Enable block-level translation cache reuse across posts'=>'Schakel blokniveau vertaalcache-hergebruik over berichten in','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Momenteel overgeslagen voor berichten die blok-opmerking attribuutplaatsaanduidingen gebruiken (wp:details samenvulvelden, enz.) — ze vallen terug op de bestaande enkele-aanvraag vertaalpad.','General'=>'Algemeen','Light'=>'Licht','Meta Description, Excerpt Generator'=>'Meta Beschrijving, Uittreksel Generator','Quality'=>'Kwaliteit','Translation, Content Generator'=>'Vertaling, Inhoudsgenerator','Active Provider'=>'Actieve provider','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Momenteel geërfd van de %s-constante. Het selecteren van een waarde hier overschrijft deze.','Models'=>'Modellen','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Functies zijn gegroepeerd in twee niveaus. Voer de exacte modelidentificatie voor elk niveau en provider in. Laat een veld leeg om de ingebouwde standaard te gebruiken (weergegeven als placeholder). Alleen de modellen van de actieve provider worden tijdens runtime aangeroepen — configureer de anderen vooraf als je wilt wisselen.','active'=>'actief','overridden'=>'overschreven','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: om een model terug te zetten naar de ingebouwde standaard, wis het veld en sla op.','Glossary'=>'Woordenlijst','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Gebruikersbeheer van terminologietabel per taalpaar. Items worden toegevoegd aan de vertaalprompt zodat de AI voorkeurstermen consequent gebruikt — essentieel voor domeinspecifieke vocabulaire ("kWp", "PPA", "interconnection point"), merknamen die niet vertaald mogen worden, en gestandaardiseerde regelgevingsteksten. Beide taalvelden zijn optioneel: laat "Bron taal" leeg om de invoer toe te passen ongeacht vanuit welke taal je vertaalt; laat "Doeltaal" leeg om het op alle doeltalen tegelijk toe te passen.','Glossary entry added.'=>'Woordenlijstitem toegevoegd.','Glossary entry removed.'=>'Woordenlijstitem verwijderd.','Could not add entry: source term and target term are required.'=>'Kan item niet toevoegen: bronterm en doeltaal zijn verplicht.','Could not save the glossary entry.'=>'Kan het woordenlijstitem niet opslaan.','Source language'=>'Bron taal','— Any —'=>'— Any —','Target language'=>'Doeltaal','— Any target —'=>'— Elke doeltaal —','Filter'=>'Filter','Reset'=>'Reset','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Geen woordenlijstitems die overeenkomen met het huidige filter. Wis het filter om alle items te zien, of voeg hieronder een nieuw item toe.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Nog geen woordenlijstitems. Voeg er hieronder een toe om terminologie in vertalingen af te dwingen.','Source term'=>'Bronterm','Target term'=>'Doeltaal','Source lang'=>'Bron taal','Target lang'=>'Doeltaal','Notes'=>'Notities','any'=>'any','Delete this glossary entry?'=>'Wil je dit woordenlijstitem verwijderen?','Delete'=>'Verwijderen','Add new entry'=>'Nieuw item toevoegen','The phrase as it appears in the source text.'=>'De uitdrukking zoals deze in de brontekst voorkomt.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hoe het in de vertaling moet verschijnen. Typ dezelfde waarde als de bronterm om de AI te instrueren deze woord voor woord te behouden.','— Any source language —'=>'— Elke bron taal —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Laat leeg voor merknamen en taal-onafhankelijke termen die ongeacht de taal waarin we vertalen gehandhaafd moeten worden.','— Any target language —'=>'— Elke doeltaal —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Laat leeg om deze invoer op alle doeltalen toe te passen — ideaal voor merknamen, afkortingen en termen die in elke vertaling woord voor woord behouden moeten blijven.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optioneel context voor editors (bijv. "ASIC = Application-Specific Integrated Circuit; in technische contexten in het Engels behouden").','Add entry'=>'Item toevoegen','Limits'=>'Limieten','Authors and above (edit_published_posts)'=>'Auteurs en hoger (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Bijdragers en hoger — standaard (edit_posts)','Editors and above (edit_others_posts)'=>'Editors en hoger (edit_others_posts)','Administrators only (manage_options)'=>'Alleen beheerders (manage_options)','AI Limits & Security'=>'AI Limieten & Beveiliging','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Beperk hoeveel AI-gebruik de site kan genereren en beperk welke gebruikersrollen betaalde AI-aanroepen kunnen triggeren. Staat boven de per-gebruiker limiet (30 verzoeken / minuut, hardcoded) die al bescherming biedt tegen runaway loops van één gebruiker.','Daily request limit'=>'Dagelijkse verzoeklimiet','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Site-brede plafond op AI-verzoeken per UTC-dag (telt zowel Toolbar-vertalingen als blokwijzigingen). Teller wordt gereset om middernacht UTC. Zet op 0 om de limiet uit te schakelen.','Minimum role'=>'Minimale rol','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Laagste WordPress-capability die toegestaan is om AI-functies te activeren. Het aanscherpen hiervan op multi-auteur sites voorkomt dat bijdragers of proefaccounts betaalde AI-aanroepen uitvoeren. Overschrijf per functie via de linguaforge_required_capability filter.','Translation Limits'=>'Vertaal Limieten','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Beheer hoeveel inhoud naar de AI wordt gestuurd en hoe groot het antwoord mag zijn. Laat een veld leeg om de ingebouwde standaard te gebruiken (als placeholder weergegeven). Verhoog deze waarden als grote pagina\'s worden afgekapt; verlaag ze om API-kosten te verminderen.','Model tier'=>'Modelniveau','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kwaliteit (standaard — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Licht (snel en kosteneffectief — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Welk modelniveau te gebruiken voor volledige pagina vertaling. Kwaliteit gebruikt het model dat in de Models tabel hierboven is geconfigureerd en wordt aanbevolen voor nauwkeurige, lange vertalingen. Schakel over naar Licht alleen als snelheid of kosten prioriteit heeft en de inhoud kort is.','Max output tokens'=>'Maximaal output tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximaal aantal tokens dat de AI in één vertaalantwoord mag produceren. Als een vertaling stilletjes wordt afgekapt, verhoog dan deze waarde. Standaard: 16.000.','Max input characters'=>'Maximaal invoer tekens','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximum aantal tekens van de berichtinhoud die naar de AI wordt doorgestuurd. 0 betekent geen limiet — de volledige inhoud wordt altijd verzonden (aanbevolen). Stel een niet-nul waarde in alleen als je provider een strakke contextvenster heeft. Er wordt een waarschuwing geschreven naar het PHP-foutlog wanneer de inhoud wordt ingekort.','Quick Translation'=>'Snelle Vertaling','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Snelle Vertaling wordt gebruikt voor snippet/fragmentmodus — korte passages vertaald op aanvraag vanuit de werkbalk, editor of blokpopovers. Het gebruikt een aparte, lichtere configuratie dan de volledige pagina vertaling om reacties snel en kosteneffectief te houden.','Light (default — fast and cost-effective)'=>'Licht (standaard — snel en kosteneffectief)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kwaliteit (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'De Light-tier gebruikt het snelle model dat is geconfigureerd in de Models-tabel hierboven (standaard: Haiku / Flash). Schakel over naar Kwaliteit als je dezelfde vertaalkauwiteit nodig hebt als in de volledige pagina modus voor snippets.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximaal tokens die de AI mag produceren per snelle vertaling. Standaard: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximaal toegestane tekens uit het invoerveld. Standaard: 8.000.','Content Generator'=>'Content Generator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Regelt het tokenbudget en de invoerlimieten voor de AI Content Generator-functie. Laat velden leeg om de ingebouwde standaardwaarden te gebruiken.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximaal tokens die de AI mag produceren per generatie. Verhoog dit als volledige artikelen worden afgekapt. Standaard: 8.192.','Max hints characters'=>'Max hints tekens','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximaal gelezen tekens uit het hints-veld. Standaard: 2.000.','Max context characters'=>'Max context tekens','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximaal aantal tekens van bestaande berichtinhoud dat wordt doorgegeven aan de AI als zaadcontext wanneer geen hints worden gegeven. Standaard: 6.000.','Maintenance'=>'Onderhoud','Language Overrides'=>'Taal Overrides','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Upload gecompileerde .mo-bestanden om strings van derden plugin te overschrijven voor specifieke regio\'s — bijvoorbeeld een aangepaste VikBooking vertaling die "appartement" gebruikt in plaats van "kamer". Bestanden moeten voldoen aan de WordPress-naamgevingsconventie: {textdomain}-{locale}.mo (bijv. vikbooking-ca.mo). Ze worden opgeslagen in de uploads-map en blijven bestaan na plugin-updates.','Override file uploaded successfully.'=>'Overschrijvingsbestand succesvol geüpload.','Override file deleted.'=>'Overschrijvingsbestand verwijderd.','No file was selected.'=>'Geen bestand geselecteerd.','Only .mo files are accepted.'=>'Alleen .mo-bestanden worden geaccepteerd.','The upload failed — please try again.'=>'De upload is mislukt — probeer het opnieuw.','Could not save the file. Check that the uploads folder is writable.'=>'Kon het bestand niet opslaan. Controleer of de uploads-map schrijfbaar is.','Invalid filename.'=>'Ongeldig bestandsnaam.','Security check failed — file path is not permitted.'=>'Beveiligingscontrole mislukt — bestandslocatie is niet toegestaan.','An unknown error occurred.'=>'Er is een onbekende fout opgetreden.','Text domain / locale'=>'Tekstdomein / regio','Files'=>'Bestanden','Size'=>'Grootte','Delete all files for this override (both .mo and .po)?'=>'Verwijder alle bestanden voor deze overschrijving (zowel .mo als .po)?','No override files uploaded yet.'=>'Nog geen overschrijvingsbestanden geüpload.','Upload .mo file'=>'Upload .mo-bestand','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepteert alleen gecompileerde .mo-bestanden. Bestandsnaam moet het patroon {textdomain}-{locale}.mo volgen. Het uploaden van een bestand met dezelfde naam als een bestaand bestand zal het vervangen.','Upload Override'=>'Upload Overschrijving','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopieer naar Veilige Opslag','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate slaat zijn aangepaste vertalingen op in wp-content/languages/loco/ — een locatie die stilletjes kan worden gewist door een WP-kernupdate, plugin-herinstallatie, of als Loco Translate zelf wordt verwijderd. Bestanden hier kopiëren verplaatst ze naar de Lingua Forge i18n-overrides directory, die door al die gebeurtenissen blijft bestaan en automatisch wordt geladen bij elk verzoek.','File copied to safe storage successfully.'=>'Bestand succesvol gekopieerd naar veilige opslag.','Source file not found.'=>'Bronbestand niet gevonden.','Could not copy the file. Check that the uploads folder is writable.'=>'Kon het bestand niet kopiëren. Controleer of de uploads-map schrijfbaar is.','Invalid file reference.'=>'Ongeldige bestandsreferentie.','Type'=>'Type','✓ In safe storage'=>'✓ In veilige opslag','Copy to safe storage'=>'Kopieer naar veilige opslag','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Nog geen aangepaste Loco Translate-bestanden gevonden. Ze verschijnen hier zodra je een vertaling opslaat in Loco Translate.','AI Cache'=>'AI Cache','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge cachet AI-gegenereerde vertalingen, meta-beschrijvingen, uittreksels en gegenereerde inhoud per bericht zodat ongewijzigde invoer geen betaalde API-aanroep opnieuw triggert. Gecachte items worden automatisch ongeldig gemaakt wanneer hun invoer verandert. Maak de cache handmatig leeg om database ruimte vrij te maken, een resync te forceren na het wisselen van provider of het bewerken van prompt-sjablonen, of een cache-gerelateerd probleem op te lossen.','AI cache cleared. %d entry was removed.'=>'AI-cache geleegd. %d item(s) verwijderd.' . "\0" . 'AI-cache geleegd. %d items verwijderd.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Alle gecachte AI-resultaten wissen? Toekomstige verzoeken zullen nieuwe API-aanroepen triggeren totdat de cache opnieuw is opgebouwd.','Clear AI Cache'=>'AI-cache wissen','Debug Files'=>'Foutopsporingsbestanden','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wanneer foutopsporing is ingeschakeld (via de schakelaar hieronder of door LINGUAFORGE_AI_DEBUG te definiëren in wp-config.php), schrijven de vertaal- en FSE-sjabloonvertalingsfuncties hun ruwe AI-prompts en antwoorden naar schijf voor probleemoplossing. Gebruik deze sectie om die output te controleren en te wissen zodra je hebt wat je nodig hebt — de bestanden kunnen snel groeien op grote pagina\'s. Configureer de doelmap via de linguaforge_debug_dir filter.','Debug files cleared. %d file was removed.'=>'Foutopsporingsbestanden gewist. %d bestand is verwijderd.' . "\0" . 'Foutopsporingsbestanden gewist. %d bestanden zijn verwijderd.','Debug logging enabled.'=>'Foutopsporing ingeschakeld.','Debug logging disabled.'=>'Foutopsporing uitgeschakeld.','Debug logging'=>'Foutopsporing','Write AI prompts and responses to disk for troubleshooting'=>'Schrijf AI-prompts en antwoorden naar schijf voor probleemoplossing','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Geforceerd AAN door de LINGUAFORGE_AI_DEBUG-constante in wp-config.php. Verwijder die regel om deze schakelaar hier te regelen.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Geforceerd UIT door de LINGUAFORGE_AI_DEBUG-constante in wp-config.php. Verwijder die regel om deze schakelaar hier te regelen.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Bestanden worden opgeslagen in de onderstaande map. Handig voor het diagnosticeren van vertaalproblemen — zet het uit zodra je hebt wat je nodig hebt zodat de bestanden niet ophopen. Je kunt dit ook forceren vanuit wp-config.php met `define( \'LINGUAFORGE_AI_DEBUG\', true );` wat deze schakelaar overschrijft.','Currently:'=>'Momenteel:','✓ Enabled'=>'✓ Ingeschakeld','✗ Disabled'=>'✗ Uitgeschakeld','Directory'=>'Map','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter met linguaforge_debug_dir om debug-uitvoer naar een niet-openbare locatie te leiden.','.txt file(s) in the directory'=>'.txt-bestand(en) in de map','Save Debug Setting'=>'Debug-instelling opslaan','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Verwijder alle .txt-bestanden in de debugmap? De map zelf blijft bestaan zodat toekomstige debug-schrijfbeurten nog steeds correct worden opgeslagen.','Clear Debug Files'=>'Debug-bestanden wissen','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Per-blok vertaalcache gedeeld tussen berichten. In- of uitschakelen in Instellingen → Gedrag. Statistieken hieronder tonen wat momenteel in de cache staat; wissen dwingt dat elk blok opnieuw wordt vertaald bij de volgende aanvraag (handig na het upgraden van modellen of om database-ruimte vrij te maken).','Translation Memory cleared. %d cached block was removed.'=>'Vertaalgeheugen gewist. %d gecachte blok is verwijderd.' . "\0" . 'Vertaalgeheugen gewist. %d gecachte blokken zijn verwijderd.','Status'=>'Status','— toggle in Settings → Behavior.'=>'— schakel in Instellingen → Gedrag.','Cached blocks'=>'Gecachte blokken','Cumulative cache hits'=>'Cumulatieve cache-hits','(avg %.1f hits/block)'=>'(gemiddeld %.1f hits/blok)','Oldest entry'=>'Oudste invoer','Newest entry'=>'Nieuwste invoer','Approximate size'=>'Geschatte grootte','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Maak het hele Vertaalgeheugen leeg? Toekomstige vertalingen zullen de cache opnieuw opbouwen terwijl ze worden uitgevoerd.','Clear Translation Memory'=>'Vertaalgeheugen wissen','Uninstall Behaviour'=>'Oninstallatiegedrag','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Regelt wat er gebeurt wanneer een beheerder de plugin verwijdert via Plugins → Geïnstalleerde plugins → Verwijderen. Plugin-instellingen en AI-caches worden altijd verwijderd. Taaltoewijzingen en vertaalrelaties worden standaard bewaard zodat een per ongeluk deïnstallatie of herinstallatie kan hervatten waar het was gebleven.','Uninstall setting saved.'=>'Deïnstallatie-instelling opgeslagen.','Delete content data on uninstall'=>'Verwijder inhoudsgegevens bij deïnstallatie','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Verwijder ook taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, woordenlijst en Vertaalgeheugen wanneer de plugin wordt verwijderd.','Warning:'=>'Waarschuwing:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Als dit is aangevinkt, wordt bij het verwijderen van de plugin alle taaltoewijzingen, vertaalrelaties, meta-beschrijvingen, paginapresets, het AI-woordenboek en Vertaalgeheugen permanent verwijderd voor elke bericht op deze site. Dit kan niet worden teruggedraaid. Laat het uitgevinkt tenzij je volledig meertalige ondersteuning van de site verwijdert.','Save Uninstall Setting'=>'Instelling voor deïnstallatie opslaan','Router'=>'Router','Primary language saved.'=>'Primaire taal opgeslagen.','Permalink rules flushed successfully.'=>'Permalink-regels succesvol gewist.','Primary Language'=>'Primaire taal','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'De primaire taal wordt altijd op de root van je site bediend — geen URL-prefix in padmodus, geen taal-subdomein in subdomeinmodus. Alle andere talen gebruiken of een /taal/ padprefix (bijvoorbeeld example.com/de/) of een taal-subdomein (bijvoorbeeld de.example.com), afhankelijk van de URL-structuur hieronder.','Primary language'=>'Primaire taal','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Na het wijzigen van de primaire taal, wis de permalinks (sectie hieronder) zodat de URL-routing wordt bijgewerkt.','URL structure'=>'URL-structuur','Path prefix — example.com/de/'=>'Padvoorvoegsel — example.com/de/','Subdomain — de.example.com/'=>'Subdomein — de.voorbeeld.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Subdomeinmodus vereist dat je webserver alle taal-subdomeinen (bijvoorbeeld de.voorbeeld.com) naar deze WordPress-installatie wijst. Na het overschakelen van modi, vernieuw de permalinkregels en wis alle caches. Als je start-URL www bevat (bijvoorbeeld www.voorbeeld.com), gebruik dan de lf_base_domain filter om het bare apex-domein in te stellen zodat subdomeinen correct worden opgebouwd.','Browser language redirect'=>'Browsertaal omleiding','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Verwijs bezoekers door naar hun voorkeurstaal op basis van de Accept-Language header van de browser','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wanneer ingeschakeld, worden eerste keer bezoekers zonder taalcookie en zonder taalprefix in de URL doorgestuurd naar de dichtstbijzijnde overeenkomende taalversie. De omleiding wordt overgeslagen als de voorkeurstaal van de browser niet onder de actieve routertalen valt. Zodra een bezoeker een taal kiest via de switcher, krijgt de cookie prioriteit en wordt de browserheader genegeerd bij alle toekomstige bezoeken.','Save Router Settings'=>'Routerinstellingen opslaan','Flush Permalinks'=>'Permalinks verversen','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Hernoopt WordPress herschrijfregels zodat URL-prefixen, taalspecifieke slugs en archiefherschrijvingen allemaal in sync zijn. Nodig na het wijzigen van de primaire taal of het toevoegen van nieuwe taalondersteuning.','Flush Permalink Rules'=>'Permalinkregels verversen','Active Languages'=>'Actieve talen','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Talen die momenteel bekend zijn bij de router (afgeleid van geïnstalleerde WordPress locale-pakketten plus de primaire taal). Installeer extra taalpakketten in het onderstaande gedeelte om meer talen beschikbaar te maken voor routering en vertaling.','%d locale pack installed.'=>'%d locale-pakket geïnstalleerd.' . "\0" . '%d locale-pakketten geïnstalleerd.','Install a Language'=>'Een taal installeren','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Download en installeer een WordPress kern taalpakket rechtstreeks van WordPress.org. Zodra geïnstalleerd, wordt de locale beschikbaar voor URL-routering en de AI-vertalingsworkflow. De lijst met beschikbare talen wordt op aanvraag opgehaald — klik op de knop hieronder om deze te laden.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Taalinstallatie is uitgeschakeld op deze server. De constante DISALLOW_FILE_MODS is ingesteld in wp-config.php. Installeer taalpakketten handmatig via WP-CLI: wp language core install de_DE','Load available languages'=>'Beschikbare talen laden','— select a language —'=>'— kies een taal —','Install'=>'Installeren','Language Setup'=>'Taalinstelling','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Geen secundaire talen geconfigureerd. Installeer een taalpakket hierboven om sjabloonopbouw mogelijk te maken.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Kies een taal om de FSE-sjablonen, sjabloononderdelen en navigatiemenu\'s te beheren.','Forbidden'=>'Verboden','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Taalinstallatie is uitgeschakeld op deze server (DISALLOW_FILE_MODS is ingesteld).','Invalid locale code.'=>'Ongeldige locale-code.','Language %s installed successfully.'=>'Taal %s succesvol geïnstalleerd.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Taalpakketinstallatie mislukt. De taal is mogelijk al geïnstalleerd, de locale-code is mogelijk onjuist, of je server blokkeert bestandschrijfbevoegdheden.','Navigations'=>'Navigaties','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigatievertaling vereist een actieve AI-provider. Configureer een API-sleutel in het tabblad API-sleutels.','Navigation'=>'Navigatie','Action'=>'Actie','Re-translate'=>'Hertaal opnieuw','CPT Block Patterns'=>'CPT-blokpatronen','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patronen geregistreerd voor aangepaste berichttypen. Gebruik de Vertaal-knop om een taalvariant te produceren. De vertaalde inhoud wordt hier opgeslagen en kan worden gekopieerd naar elk CPT-bericht vanuit de blokeditor Pattern-inserter of gebruikt als uitgangspunt voor een Gesynchroniseerd patroon (Herbruikbaar blok).','Pattern'=>'Patroon','Post Types'=>'Berichttypen','✓ Translation saved'=>'✓ Vertaling opgeslagen','View'=>'Bekijken','Template Parts'=>'Sjabloononderdelen','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Taal-specifieke kopieën van de sjabloononderdelen van het thema. Zodra ze zijn opgebouwd, worden sjablonen bijgewerkt om te verwijzen naar het taal-specifieke onderdeel.','Part'=>'Onderdeel','Status / Actions'=>'Status / Acties','Fix Links'=>'Links corrigeren','Fix Nav'=>'Navigatie corrigeren','Create'=>'Aanmaken','Templates'=>'Sjablonen','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-sjablonen gezaaid vanuit het actieve thema. Maak ze aan en pas ze aan in de Site Editor.','Actions'=>'Acties','Fix Parts'=>'Onderdelen corrigeren','Create missing'=>'Maak ontbrekend aan','Translate all'=>'Vertaal alles','Fix all parts'=>'Repareer alle onderdelen','Fix all links'=>'Repareer alle links','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Bezig met testen…','✓ Connection OK'=>'✓ Verbinding OK','✗ Failed:'=>'✗ Mislukt:','No response from provider — check the error log for details.'=>'Geen reactie van de provider — controleer het foutlog voor details.','Network error — could not reach the WordPress AJAX endpoint.'=>'Netwerkfout — kon de WordPress AJAX-eindpunt niet bereiken.','Loading…'=>'Laden…','Installing…'=>'Installeren…','✓ Language installed.'=>'✓ Taal geïnstalleerd.','✗ Error:'=>'✗ Fout:','Creating…'=>'Bezig met maken…','✓ All templates created.'=>'✓ Alle sjablonen gemaakt.','Some templates could not be created.'=>'Sommige sjablonen konden niet worden gemaakt.','✓ All parts created.'=>'✓ Alle onderdelen gemaakt.','Some parts could not be created.'=>'Sommige onderdelen konden niet worden gemaakt.','✓ All translated.'=>'✓ Alles vertaald.','Some translations failed.'=>'Sommige vertalingen zijn mislukt.','Review carefully — links and slugs not updated.'=>'Bekijk het zorgvuldig — links en slugs niet bijgewerkt.','Fixing…'=>'Bezig met repareren…','✓ Links fixed.'=>'✓ Links gerepareerd.','Some link fixes failed.'=>'Sommige linkreparaties zijn mislukt.','✓ Parts fixed.'=>'✓ Onderdelen gerepareerd.','Some part fixes failed.'=>'Sommige onderdeelreparaties zijn mislukt.','✓ Nav refs fixed.'=>'✓ Navigatieverwijzingen gerepareerd.','Some nav ref fixes failed.'=>'Sommige navigatieverwijzingen reparaties zijn mislukt.','✓ Pattern translated.'=>'✓ Patroon vertaald.','Pattern translation failed.'=>'Patroonvertaling mislukt.','Hide'=>'Verberg','Built-in preset instructions:'=>'Ingebouwde preset-instructies:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Geen ingebouwde instructies — elke AI-functie gebruikt zijn eigen afgestemde standaardinstellingen. Vul het veld \'Aangepaste prompt-instructies\' hieronder in om je eigen site-brede regels toe te voegen.','Settings'=>'Instellingen','You do not have permission to manage these settings.'=>'Je hebt geen toestemming om deze instellingen te beheren.','Lingua Forge — Settings'=>'Lingua Forge — Instellingen','Settings saved.'=>'Instellingen opgeslagen.','Save Settings'=>'Instellingen opslaan','Standard'=>'Standaard','Technical / Scientific'=>'Technisch / Wetenschappelijk','Legal / Compliance'=>'Juridisch / Compliance','Creative / Marketing'=>'Creatief / Marketing','Full Article'=>'Volledig artikel','Introduction only'=>'Alleen introductie','Structured Outline'=>'Gestructureerde schets','Generate Content'=>'Inhoud genereren','Hints'=>'Hints','Key points, ideas, or structure to build from…'=>'Belangrijke punten, ideeën of structuur om vanaf te bouwen…','Tone'=>'Toon','Output'=>'Uitvoer','Generate Excerpt'=>'Fragment genereren','Generate Meta Description'=>'Meta beschrijving genereren','Translate Content'=>'Inhoud vertalen','Mode'=>'Modus','Full post'=>'Volledige bericht','Translate chunk'=>'Chunk vertalen','Target Language'=>'Doeltaal','Text to translate'=>'Tekst om te vertalen','Paste a footnote, sentence, or any snippet here…'=>'Plak hier een voetnoot, zin of fragment…','Also generate meta description'